<script setup lang="ts">
import { computed, onBeforeUnmount, ref } from 'vue';

import { candidates, csv, discoverNetwork, latency, libraries, loadLocations, pool, speed, sortResults, type Location, type NetworkInfo, type Result } from '../features/optimizer/core';
import { appendSelections, formatSelection } from '../features/optimizer/catalogue';
const addresses = defineModel<string>({required:true});
const saveMode=ref('append');
const locations=ref<Location[]>([]);
async function copyAddress(address:string){try{await navigator.clipboard.writeText(address);message.value='已复制地址';}catch(e){fail(e);}}
const input=ref(''), source=ref(libraries[0].url), host=ref('bestcf.cmliussss.hidns.vip');
const limit=ref(512),timeout=ref(500),threads=ref(16),port=ref(443);
const results=ref<Result[]>([]),selected=ref<string[]>([]),busy=ref(false),done=ref(0),total=ref(0),message=ref(''),error=ref(''),query=ref(''),family=ref(''),status=ref(''),country=ref(''),colo=ref(''),kind=ref(''),order=ref('latency'),descending=ref(false);
const network=ref<NetworkInfo[]>([]); const autoHost=ref(true);
let controller:AbortController|undefined;
const deps={fetch:globalThis.fetch.bind(globalThis),now:()=>performance.now()};
const visible=computed(()=>sortResults(results.value.filter(r=>(!family.value||r.family===family.value)&&(!status.value||r.status===status.value)&&(!country.value||r.country===country.value)&&(!colo.value||r.colo===colo.value)&&(!kind.value||r.type===kind.value)&&`${r.address} ${r.error||''}`.toLowerCase().includes(query.value.toLowerCase())),order.value as 'latency'|'speed'|'address',descending.value));
const chosen=computed(()=>results.value.filter(r=>r.status==='ok'&&selected.value.includes(r.address)));
function fail(e:unknown){error.value=e instanceof Error?e.message:String(e);}
async function load(remote:boolean){error.value='';try{if(remote){const url=new URL(source.value);if(!['https:','http:'].includes(url.protocol))throw Error('请输入 HTTP 来源');const response=await fetch(url,{cache:'no-store'});if(!response.ok||response.type==='opaque')throw Error(`来源读取失败 ${response.status}，可能受 CORS 限制`);input.value=await response.text();}else input.value=addresses.value;message.value='地址已导入；点击开始才会进行探测';}catch(e){fail(e);}}
async function file(event:Event){const f=(event.target as HTMLInputElement).files?.[0];if(f)input.value=await f.text();}
async function start(){error.value='';message.value='';try{const list=candidates(input.value,limit.value,port.value);if(!list.length)throw Error('待选列表为空');if(!Number.isFinite(timeout.value)||timeout.value<100||timeout.value>10000||!Number.isInteger(threads.value)||threads.value<1||threads.value>32)throw Error('超时应为 100–10000 ms，并发应为 1–32');busy.value=true;controller=new AbortController();const signal=controller.signal;results.value=[];selected.value=[];done.value=0;total.value=list.length;if(autoHost.value){message.value='正在识别公共探测域名和网络出口';let cached='';try{cached=localStorage.getItem('bestcf:active-best-host')||'';}catch{}const hosts=[...new Set([cached,host.value,'bestcf.cmliussss.hidns.vip','ns.psb.kdns.fr'].filter(Boolean))];const found=await discoverNetwork(hosts,signal,deps);host.value=found.host;network.value=found.network;locations.value=await loadLocations(found.network,signal,deps);if(!locations.value.length)message.value='机房地区目录读取失败：官方优选国家显示未知';try{localStorage.setItem('bestcf:active-best-host',found.host);}catch{}}await pool(list,threads.value,signal,async c=>{try{const result=await latency(c,host.value,timeout.value,signal,deps,network.value,locations.value);if(!signal.aborted)results.value.push(result);}catch(e){results.value.push({...c,country:'未知',colo:'未知',type:'未验证',status:signal.aborted?'cancelled':'failed',error:e instanceof Error?`${e.message}（浏览器 DNS / TLS / CORS 限制也可能导致失败）`:'网络 / CORS / TLS 请求失败'});}finally{done.value++;}});message.value=signal.aborted?'任务已取消，保留已完成结果':'延迟探测完成';}catch(e){fail(e);}finally{busy.value=false;}}
async function measure(targets:Result[]){if(!targets.length)return;error.value='';busy.value=true;controller=new AbortController();const signal=controller.signal;done.value=0;total.value=targets.length;await pool(targets,Math.max(1,Math.ceil(threads.value/8)),signal,async r=>{r.error=undefined;try{r.speed=await speed(r,host.value,signal,deps,v=>{r.speed=v;});}catch(e){r.speed=undefined;r.error=e instanceof Error?e.message:'测速失败';}finally{done.value++;}});message.value=signal.aborted?'测速已取消':'测速完成';busy.value=false;}
function stop(){controller?.abort();}onBeforeUnmount(stop);
function selectVisible(invert=false){const set=new Set(selected.value);visible.value.filter(r=>r.status==='ok').forEach(r=>{if(invert&&set.has(r.address))set.delete(r.address);else set.add(r.address);});selected.value=[...set];}
function save(){error.value='';addresses.value=appendSelections(addresses.value,chosen.value.map(formatSelection),saveMode.value==='replace');message.value='已填入自定义优选草稿，请返回优选订阅页面保存';}
function download(format:'text'|'csv'){const rows=chosen.value.length?chosen.value:visible.value;const blob=new Blob([format==='csv'?csv(rows):rows.filter(r=>r.status==='ok').map(r=>r.address).join('\n')],{type:format==='csv'?'text/csv;charset=utf-8':'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`bestcf-results.${format==='csv'?'csv':'txt'}`;a.click();URL.revokeObjectURL(url);}
</script>
<template>
  <section class="subscription-optimizer">

<section class="card"><h2>地址来源</h2><label>公共 IP 库<select v-model="source" :disabled="busy"><option v-for="library in libraries" :key="library.url" :value="library.url">{{ library.label }}</option></select></label><label>来源 URL<input v-model="source" :disabled="busy" /></label><div class="actions"><button type="button" :disabled="busy" @click="load(true)">读取来源</button><button type="button" :disabled="busy" @click="load(false)">读取当前地址草稿</button><label>导入文本文件<input type="file" accept=".txt,.csv" :disabled="busy" @change="file" /></label></div><label>待选地址（IPv4 / IPv6 / 域名、CIDR、IP 区间；每行一条）<textarea v-model="input" rows="8" :disabled="busy" /></label><p>大范围按数量上限均匀采样；端口 0 在 TLS 端口列表轮换。</p>
<div class="settings"><label>数量上限<input v-model.number="limit" type="number" min="1" max="4096" :disabled="busy" /></label><label>超时 ms<input v-model.number="timeout" type="number" min="100" max="10000" :disabled="busy" /></label><label>并发<input v-model.number="threads" type="number" min="1" max="32" :disabled="busy" /></label><label>端口<input v-model.number="port" type="number" min="0" max="65535" :disabled="busy" /></label><label>IP 探测域名<input v-model="host" :disabled="busy" list="probe-hosts" /></label></div><label><input v-model="autoHost" type="checkbox" :disabled="busy" />开始时自动识别探测域名与当前网络出口</label><p v-for="n in network" :key="n.ip">{{ n.ipType }} 出口 {{ n.ip }} · {{ n.country }} · {{ n.colo }} · {{ n.cnIspCode || '未知运营商' }}</p><datalist id="probe-hosts"><option>bestcf.cmliussss.hidns.vip</option><option>ns.psb.kdns.fr</option></datalist><div class="actions"><button type="button" :disabled="busy" @click="start">开始延迟优选</button><button type="button" :disabled="!busy" @click="stop">取消任务</button></div><p role="status">{{ done }} / {{ total }} {{ message }}</p><progress :value="done" :max="total || 1" /></section>
<section class="card"><h2>结果 {{ visible.length }} / {{ results.length }}</h2><div class="settings"><label>搜索<input v-model="query" /></label><label>IP 类型<select v-model="family"><option value="">全部</option><option>ipv4</option><option>ipv6</option><option>domain</option></select></label><label>状态<select v-model="status"><option value="">全部</option><option value="ok">可读取</option><option value="failed">失败</option><option value="cancelled">取消</option></select></label><label>国家<select v-model="country"><option value="">全部</option><option v-for="v in [...new Set(results.map(r=>r.country))]" :key="v">{{ v }}</option></select></label><label>机房<select v-model="colo"><option value="">全部</option><option v-for="v in [...new Set(results.map(r=>r.colo))]" :key="v">{{ v }}</option></select></label><label>优选类型<select v-model="kind"><option value="">全部</option><option v-for="v in [...new Set(results.map(r=>r.type))]" :key="v">{{ v }}</option></select></label><label>排序<select v-model="order"><option value="latency">延迟</option><option value="speed">速度</option><option value="address">地址</option></select></label><label><input v-model="descending" type="checkbox" />降序</label></div><div class="actions"><button type="button" @click="selectVisible()">全选可见</button><button type="button" @click="selectVisible(true)">反选可见</button><button type="button" @click="selected=[]">清空选择</button><button type="button" :disabled="busy || !chosen.length" @click="measure(chosen)">测速所选</button><button type="button" :disabled="busy || !results.some(r=>r.status==='ok')" @click="measure(results.filter(r=>r.status==='ok'))">全部测速</button></div><div class="table-wrap"><table><thead><tr><th>选择</th><th>地址</th><th>类型</th><th>优选类型</th><th>国家 / 机房</th><th>延迟 ms</th><th>Mbps</th><th>状态 / 限制</th><th>测速</th></tr></thead><tbody><tr v-for="r in visible" :key="r.address"><td><input v-model="selected" type="checkbox" :value="r.address" :disabled="r.status!=='ok'" :aria-label="`选择 ${r.address}`" /></td><td><button type="button" class="secondary" @click="copyAddress(r.address)">{{ r.address }}</button></td><td>{{ r.family }}</td><td>{{ r.type }}</td><td>{{ r.country }} / {{ r.colo }}</td><td>{{ r.latency ?? '—' }}</td><td>{{ r.speed?.toFixed(2) ?? '—' }}</td><td>{{ r.error || r.status }}</td><td><button type="button" :disabled="busy || r.status!=='ok'" @click="measure([r])">测速</button></td></tr></tbody></table></div><p>已选择 {{ chosen.length }} 个；下载测速每个地址最多 10 秒 / 20 MB。</p><label>保存方式<select v-model="saveMode" :disabled="busy"><option value="append">追加到当前地址草稿（默认）</option><option value="replace">替换全部现有地址</option></select></label><div class="actions"><button type="button" :disabled="busy || !chosen.length" @click="save">填入自定义优选</button><button type="button" :disabled="!results.length" @click="download('text')">导出文本</button><button type="button" :disabled="!results.length" @click="download('csv')">导出 CSV</button></div><p>有选择时导出所选，否则导出可见结果。CSV 包含失败原因。</p></section><p v-if="error" role="alert" class="error">{{ error }}</p>

  </section>
</template>
<style scoped>.settings{display:flex;gap:1rem;flex-wrap:wrap}.settings label{flex:1;min-width:130px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:.6rem;text-align:left;border-bottom:1px solid var(--border,#ddd)}progress{width:100%}</style>
